sys_script_include.script:
var CheckEventLocationAvailability = Class.create();
CheckEventLocationAvailability.prototype = Object.extendsObject(AbstractAjaxProcessor, {

  isLocationAvailable: function() {
    var location = this.getParameter('sysparm_location');
    var eventDate = this.getParameter('sysparm_event_date');

    var gr = new GlideRecord('x_1790116_event_ma_event'); 
    gr.addQuery('u_location', location);
    gr.addQuery('u_event_date', eventDate);
    gr.query();

    if (gr.next()) {
      return "false";
    }
    return "true"; 
  }

});
